/* ============================ SHARED UI ============================ */

const chip = (active) => active
  ? { border: '1px solid #14120f', background: '#14120f', color: '#f5f3ee' }
  : { border: '1px solid #c9c3b4', background: 'transparent', color: '#4a453d' };

function MonoLabel({ children, style }) {
  return <div className="mono-label" style={{ lineHeight: 1.7, ...style }}>{children}</div>;
}

function Logo({ size = 19 }) {
  return (
    <svg viewBox="0 0 100 100" width={size} height={size} aria-hidden="true">
      <line x1="34" y1="20" x2="34" y2="80" stroke="#14120f" strokeWidth="9" />
      <line x1="34" y1="50" x2="74" y2="50" stroke={ACCENT} strokeWidth="9" />
    </svg>
  );
}

function DarkCode({ children, pad = 'clamp(18px, 2vw, 26px)', style }) {
  return (
    <div className="noscroll" style={{ background: '#14120f', color: '#e8e4da', padding: pad, overflowX: 'auto', ...style }}>
      <pre style={{ margin: 0, fontFamily: 'var(--font-mono)', fontSize: 'clamp(12px, 1.05vw, 13.5px)', lineHeight: 1.85 }}>{children}</pre>
    </div>
  );
}

const K = ({ children }) => <span style={{ color: 'var(--code-kw)' }}>{children}</span>;
const Ty = ({ children }) => <span style={{ color: 'var(--code-ty)' }}>{children}</span>;
const Sec = ({ children }) => <span style={{ color: 'var(--code-sec)' }}>{children}</span>;
const Fn = ({ children }) => <span style={{ color: 'var(--code-fn)' }}>{children}</span>;
const Str = ({ children }) => <span style={{ color: 'var(--code-str)' }}>{children}</span>;
const Err = ({ children }) => <span style={{ color: 'var(--code-err)' }}>{children}</span>;
const Dim = ({ children }) => <span style={{ color: 'var(--dark-faint)' }}>{children}</span>;
const Prompt = () => <span style={{ color: 'var(--code-prompt)' }}>$ </span>;

