function Evidence({ metrics }) {
  const [q, setQ] = useState('');
  const [tier, setTier] = useState('all');
  const [open, setOpen] = useState(null);
  const tiers = metrics.quality?.coqTiers || {};
  const query = q.trim().toLowerCase();
  const rows = EV
    .filter(e => tier === 'all' || e.tier === tier)
    .filter(e => !query || e.name.toLowerCase().includes(query) || e.claim.toLowerCase().includes(query));
  const stat = (v, label, accent) => (
    <div style={{ background: '#f5f3ee', padding: '18px 20px' }}>
      <div style={{ fontFamily: 'var(--font-mono)', fontSize: 'clamp(22px, 2vw, 27px)', fontWeight: 500, color: accent ? ACCENT : undefined }}>{v}</div>
      <div style={{ fontSize: 13, color: '#4a453d', marginTop: 4 }}>{label}</div>
    </div>
  );
  return (
    <div className="rise">
      <div className="shell" style={{ paddingTop: 'clamp(40px, 5vw, 68px)', paddingBottom: 'clamp(24px, 3vw, 34px)' }}>
        <MonoLabel style={{ marginBottom: 18 }}>Evidence ledger &middot; {metrics.git?.commit || ''}</MonoLabel>
        <h1 className="serif-h1" style={{ marginBottom: 16, fontSize: 'clamp(36px, 4.6vw, 58px)', maxWidth: 900 }}>An index over the corpus, not a summary of it.</h1>
        <p style={{ margin: 0, fontSize: 'clamp(15.5px, 1.2vw, 17px)', lineHeight: 1.65, color: '#3a352d', maxWidth: 700 }}>
          Every entry names the file it lives in and the command that re-checks it. Nothing here asks you to believe a number &mdash; open a row, run the command, compare.
        </p>
      </div>

      <div className="shell" style={{ paddingBottom: 'clamp(20px, 2.4vw, 28px)' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 1, background: '#d8d3c7', border: '1px solid #d8d3c7' }}>
          {stat(fmt(tiers.core || 0), 'core theorems')}
          {stat(fmt(tiers.domain || 0), 'domain theorems')}
          {stat(fmt(metrics.coq?.domains || 0), 'domains covered')}
          {stat(fmt(metrics.proofs?.admitted || 0), `admitted · ${fmt(metrics.proofs?.axioms || 0)} axiom declarations`, true)}
        </div>
      </div>

      <div className="shell" style={{ paddingBottom: 'clamp(60px, 7vw, 90px)' }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center', justifyContent: 'space-between', padding: '22px 0 18px' }}>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {['all', 'core', 'domain', 'bridge'].map(t => (
              <button key={t} onClick={() => setTier(t)} style={{ fontFamily: 'var(--font-mono)', fontSize: 11.5, letterSpacing: '0.1em', textTransform: 'uppercase', padding: '8px 13px', cursor: 'pointer', ...chip(tier === t) }}>
                {t}
              </button>
            ))}
          </div>
          <input value={q} onChange={e => setQ(e.target.value)} placeholder="Filter by theorem or property" className="field"
            style={{ flex: 1, minWidth: 220, maxWidth: 340, background: '#fffdf8', border: '1px solid #c9c3b4', padding: '10px 14px', fontSize: 14, color: '#14120f' }} />
        </div>

        <div style={{ borderTop: '1px solid #14120f' }}>
          {rows.map(rowData => {
            const isOpen = open === rowData.name;
            const core = rowData.tier === 'core';
            return (
              <div key={rowData.name} style={{ borderBottom: '1px solid #e6e1d6', background: isOpen ? '#fffdf8' : 'transparent' }}>
                <button onClick={() => setOpen(isOpen ? null : rowData.name)}
                  style={{ width: '100%', textAlign: 'left', background: 'none', border: 'none', padding: '18px 4px', cursor: 'pointer', display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: '10px 16px', color: '#14120f' }}>
                  <span style={{ fontFamily: 'var(--font-mono)', fontSize: 10, letterSpacing: '0.12em', textTransform: 'uppercase', color: core ? ACCENT : '#6b6559', border: `1px solid ${core ? ACCENT : '#c9c3b4'}`, padding: '3px 7px', flexShrink: 0 }}>{rowData.tier}</span>
                  <span style={{ fontFamily: 'var(--font-mono)', fontSize: 14.5, fontWeight: 500, wordBreak: 'break-word' }}>{rowData.name}</span>
                  <span style={{ fontSize: 14, color: '#4a453d', flex: 1, minWidth: 200 }}>{rowData.claim}</span>
                  <span style={{ fontFamily: 'var(--font-mono)', fontSize: 15, color: '#6b6559', flexShrink: 0 }}>{rowData.sign}</span>
                </button>
                {isOpen && (
                  <div style={{ padding: '4px 4px 26px', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 22 }}>
                    <div>
                      <div className="mono-label-sm" style={{ fontSize: 10, letterSpacing: '0.12em', marginBottom: 8 }}>What it establishes</div>
                      <div style={{ fontSize: 14.5, lineHeight: 1.65, color: '#3a352d' }}>{rowData.statement}</div>
                      <div style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: ACCENT, marginTop: 12, wordBreak: 'break-all' }}>{rowData.file}</div>
                    </div>
                    <div style={{ background: '#14120f', color: '#e8e4da', padding: '16px 18px' }}>
                      <div style={{ fontFamily: 'var(--font-mono)', fontSize: 10, letterSpacing: '0.12em', textTransform: 'uppercase', color: '#8a8378', marginBottom: 10 }}>Re-check this yourself</div>
                      <div className="noscroll" style={{ overflowX: 'auto', fontFamily: 'var(--font-mono)', fontSize: 12.5, lineHeight: 1.9 }}>
                        <div style={{ whiteSpace: 'nowrap' }}><Prompt />{rowData.cmd}</div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {rows.length === 0 && (
          <div style={{ padding: '40px 4px', fontSize: 15, color: '#6b6559' }}>
            No entry matches that filter. The full corpus is browsable in the repository under <span style={{ fontFamily: 'var(--font-mono)', color: '#14120f' }}>02_FORMAL/coq</span>.
          </div>
        )}

        <div style={{ marginTop: 34, border: '1px solid #c9c3b4', background: '#efece4', padding: '22px 24px', fontSize: 14, lineHeight: 1.68, color: '#4a453d' }}>
          <strong style={{ color: '#14120f' }}>On honesty.</strong> This ledger indexes the mechanized Coq lane only. The active build also carries 30 documented <span style={{ fontFamily: 'var(--font-mono)' }}>Parameter</span> declarations &mdash; interface assumptions with written rationales, enforced by <span style={{ fontFamily: 'var(--font-mono)' }}>scripts/audit-docs.sh</span> &mdash; and {fmt(tiers.domainTrivial || 0)} of the domain theorems are classed trivial in our own tiering. Kernel attestation goes deeper than the grep counts: <span style={{ fontFamily: 'var(--font-mono)' }}>riinac verify --full</span> runs <span style={{ fontFamily: 'var(--font-mono)' }}>Print Assumptions</span> on five capstone theorems; the sole permitted kernel dependency is the Rocq standard library&rsquo;s functional extensionality, and the gate fails the build if anything else ever appears. We publish these distinctions because an assessor would find them anyway.
        </div>
      </div>
    </div>
  );
}

/* ============================ LANGUAGE ============================ */

function Language() {
  const [tab, setTab] = useState('syntax');
  const tabBtn = (key, label) => (
    <button key={key} onClick={() => setTab(key)}
      style={{ background: 'none', border: 'none', borderBottom: `2px solid ${tab === key ? ACCENT : 'transparent'}`, padding: '12px 16px', cursor: 'pointer', whiteSpace: 'nowrap', fontSize: 14.5, color: tab === key ? '#14120f' : '#4a453d' }}>
      {label}
    </button>
  );
  return (
    <div className="rise">
      <div className="shell" style={{ paddingTop: 'clamp(40px, 5vw, 68px)', paddingBottom: 'clamp(20px, 2.6vw, 30px)' }}>
        <MonoLabel style={{ marginBottom: 18 }}>The language</MonoLabel>
        <h1 className="serif-h1" style={{ marginBottom: 16, fontSize: 'clamp(36px, 4.6vw, 58px)', maxWidth: 900 }}>Security is a type, not a convention.</h1>
        <p style={{ margin: 0, fontSize: 'clamp(15.5px, 1.2vw, 17px)', lineHeight: 1.65, color: '#3a352d', maxWidth: 700 }}>
          A secret is a distinct type the checker tracks through every expression. A side effect is declared in the signature or it does not happen. Keywords are Bahasa Melayu; the English gloss sits beside every one.
        </p>
      </div>

      <div className="shell" style={{ paddingBottom: 'clamp(60px, 7vw, 90px)' }}>
        <div className="noscroll" style={{ display: 'flex', gap: 4, overflowX: 'auto', borderBottom: '1px solid #d8d3c7', marginBottom: 'clamp(28px, 3.4vw, 40px)' }}>
          {tabBtn('syntax', 'Syntax')}
          {tabBtn('types', 'Security types')}
          {tabBtn('effects', 'Effects')}
          {tabBtn('stdlib', 'Stdlib')}
        </div>

        {tab === 'syntax' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 'clamp(30px, 4vw, 56px)', alignItems: 'start' }}>
            <div>
              {KW.map(g => (
                <div key={g.title} style={{ marginBottom: 30 }}>
                  <div className="mono-label-sm" style={{ marginBottom: 12 }}>{g.title}</div>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: 1, background: '#e6e1d6', border: '1px solid #e6e1d6' }}>
                    {g.items.map(kw => (
                      <div key={kw.bm} style={{ background: '#fffdf8', padding: '9px 12px', display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 8 }}>
                        <span style={{ fontFamily: 'var(--font-mono)', fontSize: 13, color: '#14120f' }}>{kw.bm}</span>
                        <span style={{ fontFamily: 'var(--font-mono)', fontSize: 11.5, color: '#9a9285' }}>{kw.en}</span>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            <div style={{ position: 'sticky', top: 82 }}>
              <div className="mono-label-sm" style={{ marginBottom: 12 }}>07_EXAMPLES/00_basics/sulit_dedah.rii &mdash; checks and runs on the shipped compiler</div>
              <DarkCode>
                <Dim>{'// Secrets and sanctioned declassification\n'}</Dim>
                <Dim>{'// `cetak(<secret>)` alone is a COMPILE ERROR\n\n'}</Dim>
                <K>fungsi</K> <Fn>utama</Fn>{'() -> '}<Ty>Unit</Ty> <K>kesan</K>{' Tulis {\n    cetak('}<K>dedah</K>{' ('}<K>sulit</K>{' 1234) '}<K>dengan bukti</K>{' ('}<K>sulit</K>{' 1234))\n}'}
              </DarkCode>
              <div style={{ marginTop: 14, display: 'flex', flexDirection: 'column', gap: 10 }}>
                <div style={{ fontSize: 14, lineHeight: 1.6, color: '#4a453d' }}><span style={{ fontFamily: 'var(--font-mono)', color: '#14120f' }}>sulit e</span> &mdash; classifies a value into <span style={{ fontFamily: 'var(--font-mono)' }}>Rahsia</span>. From that point it cannot reach a log, a response body or a file without declassification.</div>
                <div style={{ fontSize: 14, lineHeight: 1.6, color: '#4a453d' }}><span style={{ fontFamily: 'var(--font-mono)', color: '#14120f' }}>dedah &hellip; dengan bukti</span> &mdash; the sanctioned exit, mirroring the mechanized rule in <span style={{ fontFamily: 'var(--font-mono)' }}>Declassification.v</span>. Without it: <span style={{ fontFamily: 'var(--font-mono)' }}>error: Security violation in print sink</span>.</div>
                <div style={{ fontSize: 14, lineHeight: 1.6, color: '#4a453d' }}><span style={{ fontFamily: 'var(--font-mono)', color: '#14120f' }}>kesan Tulis</span> &mdash; the only effect this function may perform. An undeclared network call will not build.</div>
              </div>
            </div>
          </div>
        )}

        {tab === 'types' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 'clamp(30px, 4vw, 56px)', alignItems: 'start' }}>
            <div style={{ borderTop: '1px solid #14120f' }}>
              {SEC_TYPES.map(t => (
                <div key={t.name} style={{ padding: '20px 0 22px', borderBottom: '1px solid #e6e1d6' }}>
                  <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: 10, marginBottom: 8 }}>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: 16, fontWeight: 500, color: '#14120f' }}>{t.name}</span>
                    <span style={{ fontSize: 12.5, color: '#6b6559' }}>{t.en}</span>
                  </div>
                  <div style={{ fontSize: 14.5, lineHeight: 1.65, color: '#4a453d' }}>{t.desc}</div>
                </div>
              ))}
            </div>
            <div>
              <div className="mono-label-sm" style={{ marginBottom: 12 }}>The same leak, two languages</div>
              <DarkCode>
                <Dim>{'// A conventional language: compiles, leaks\n'}</Dim>
                <K>fn</K> <Fn>charge</Fn>{'(card: '}<Ty>String</Ty>{') -> '}<Ty>Receipt</Ty>{' {\n    log::info!('}<Str>"{}"</Str>{', card);  '}<Dim>{'// no error'}</Dim>{'\n    gateway::submit(card)\n}\n\n'}
                <Dim>{'// RIINA: the checker refuses it\n'}</Dim>
                <K>fungsi</K> <Fn>caj</Fn>{'(kad: '}<Sec>Rahsia</Sec>{'<'}<Ty>Teks</Ty>{'>) -> '}<Ty>Resit</Ty>{' {\n    cetak(kad);\n'}
                <Err>{'    ^^^^^^^^^^ error: Security violation in\n'}</Err>
                <Dim>{'    print sink: declassify (dedah) the secret\n    before printing it: level Secret does not\n    flow to Public\n'}</Dim>
                {'}'}
              </DarkCode>
              <div style={{ marginTop: 14, fontSize: 14, lineHeight: 1.65, color: '#4a453d' }}>
                The error text is the compiler&rsquo;s real diagnostic, verbatim. The leak was not detected &mdash; it was made unrepresentable. Laundering through conversion builtins is closed too: <span style={{ fontFamily: 'var(--font-mono)' }}>cetak(ke_teks(pin))</span> is rejected the same way.
              </div>
            </div>
          </div>
        )}

        {tab === 'effects' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 'clamp(30px, 4vw, 56px)', alignItems: 'start' }}>
            <div>
              <p style={{ margin: '0 0 22px', fontSize: 15.5, lineHeight: 1.68, color: '#3a352d' }}>
                Every side effect appears in the function signature and is tracked through the call graph. Effects compose with <span style={{ fontFamily: 'var(--font-mono)' }}>+</span>. A function cannot perform an effect its type does not carry.
              </p>
              <div style={{ borderTop: '1px solid #14120f' }}>
                {EFFECTS.map(e => (
                  <div key={e.name} style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: '10px 16px', padding: '14px 0', borderBottom: '1px solid #e6e1d6' }}>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: 14.5, fontWeight: 500, minWidth: 96 }}>{e.name}</span>
                    <span style={{ fontSize: 12.5, color: '#9a9285', minWidth: 58 }}>{e.en}</span>
                    <span style={{ fontSize: 14.5, color: '#4a453d', flex: 1, minWidth: 180 }}>{e.desc}</span>
                  </div>
                ))}
              </div>
            </div>
            <DarkCode>
              <Dim>{'// The checker’s real diagnostic for an\n// undeclared effect:\n\n'}</Dim>
              <K>fungsi</K> <Fn>utama</Fn>{'() -> '}<Ty>Unit</Ty> <K>kesan</K>{' Bersih {\n    cetak('}<Str>"hello"</Str>{');\n}\n\n'}
              <Err>{'error: Effect violation:\n       allowed Pure, found Write'}</Err>
              {'\n\n'}
              <Dim>{'// Declare it and the same body builds:\n'}</Dim>
              <K>fungsi</K> <Fn>utama</Fn>{'() -> '}<Ty>Unit</Ty> <K>kesan</K>{' Tulis {\n    cetak('}<Str>"hello"</Str>{');\n}'}
            </DarkCode>
          </div>
        )}

        {tab === 'stdlib' && (
          <div>
            <p style={{ margin: '0 0 24px', fontSize: 15.5, lineHeight: 1.68, color: '#3a352d', maxWidth: 640 }}>
              Bilingual builtins with effect-gated I/O and zero third-party runtime dependencies (the SBOM proves it). Every function that touches the outside world carries an effect in its type &mdash; and the secret-sink rule covers the I/O families below, including their sanitized variants.
            </p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: 1, background: '#e6e1d6', border: '1px solid #e6e1d6' }}>
              {STDLIB.map(m => (
                <div key={m.mod} style={{ background: '#fffdf8', padding: '18px 20px' }}>
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 6 }}>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: 14, fontWeight: 500, color: ACCENT }}>{m.mod}</span>
                    <span style={{ fontSize: 12, color: '#9a9285' }}>{m.en}</span>
                  </div>
                  <div style={{ fontFamily: 'var(--font-mono)', fontSize: 12.5, lineHeight: 1.7, color: '#4a453d', wordBreak: 'break-word' }}>{m.fns}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ============================ ARCHITECTURE ============================ */

function Architecture({ metrics }) {
  const pipeline = [
    ...PIPELINE_STATIC,
    { num: '04', title: 'Proof artefacts ship with the code', desc: `${fmt(metrics.proofs?.qedActive || 0)} machine-checked Coq proofs live in the repository with ${fmt(metrics.proofs?.admitted || 0)} admitted and ${fmt(metrics.proofs?.axioms || 0)} axiom declarations in the active build — and a kernel-attestation gate (Print Assumptions over five capstones) on every full verify. You clone them and re-check them. The other prover lanes are generated from these sources and graded separately.` },
    { num: '05', title: 'The differential keeps the backends honest', desc: 'The C and WASM backends are byte-differential-tested against the interpreter on the example corpus, and a missing test tool fails the build rather than silently skipping — a silently-skipping test counts as unverified, not green. Hardware-rooted attestation is on the roadmap and is not claimed today.' },
  ];
  const lanes = [
    { prover: metrics.coq?.prover || 'Coq / Rocq 9.1.1', count: `${fmt(metrics.proofs?.qedActive || 0)} Qed`, level: metrics.claimLevels?.coq || 'mechanized', role: 'Primary proof engine' },
    { prover: 'Lean 4', count: `${fmt(metrics.lean?.theorems || 0)} decl`, level: metrics.claimLevels?.lean || 'generated', role: 'Generated port' },
    { prover: 'Isabelle/HOL', count: `${fmt(metrics.isabelle?.lemmas || 0)} lemmas`, level: metrics.claimLevels?.isabelle || 'generated', role: 'Generated port' },
    { prover: 'Z3 / CVC5', count: `${fmt(metrics.smt?.assertions || 0)} asserts`, level: metrics.claimLevels?.smt || 'generated', role: 'SMT lane' },
    { prover: 'TLA+', count: `${fmt(metrics.tlaplus?.theorems || 0)} theorems`, level: metrics.claimLevels?.tlaplus || 'generated', role: 'Model-checking lane' },
    { prover: 'F*', count: `${fmt(metrics.fstar?.lemmas || 0)} lemmas`, level: metrics.claimLevels?.fstar || 'generated', role: 'Dependent-types lane' },
    { prover: 'Alloy 6', count: `${fmt(metrics.alloy?.assertions || 0)} asserts`, level: metrics.claimLevels?.alloy || 'generated', role: 'Relational-logic lane' },
    { prover: 'Verus', count: 'quarantined', level: metrics.claimLevels?.verus || 'generated', role: 'Rust verification lane' },
    { prover: 'Kani', count: 'quarantined', level: metrics.claimLevels?.kani || 'generated', role: 'Bounded model checking' },
    { prover: 'Translation Validation', count: 'quarantined', level: metrics.claimLevels?.tv || 'generated', role: 'Binary equivalence lane' },
  ];
  return (
    <div className="rise">
      <div className="shell" style={{ paddingTop: 'clamp(40px, 5vw, 68px)', paddingBottom: 'clamp(28px, 3.4vw, 40px)' }}>
        <MonoLabel style={{ marginBottom: 18 }}>Architecture</MonoLabel>
        <h1 className="serif-h1" style={{ marginBottom: 16, fontSize: 'clamp(36px, 4.6vw, 58px)', maxWidth: 900 }}>From a type annotation to a proof obligation.</h1>
        <p style={{ margin: 0, fontSize: 'clamp(15.5px, 1.2vw, 17px)', lineHeight: 1.65, color: '#3a352d', maxWidth: 700 }}>
          Five stages sit between the source you write and the artefact you ship. Each one either discharges an obligation or refuses the build.
        </p>
      </div>

      <div className="shell" style={{ paddingBottom: 'clamp(50px, 6vw, 72px)' }}>
        <div style={{ borderTop: '1px solid #14120f' }}>
          {pipeline.map(s => (
            <div key={s.num} style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 64px) 1fr', gap: 'clamp(16px, 2.4vw, 34px)', padding: 'clamp(22px, 2.6vw, 30px) 0', borderBottom: '1px solid #e6e1d6' }}>
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: 'clamp(24px, 2.6vw, 32px)', fontWeight: 400, color: '#c9c3b4' }}>{s.num}</div>
              <div>
                <div style={{ fontFamily: 'var(--font-serif)', fontSize: 'clamp(22px, 2.2vw, 28px)', fontWeight: 400, marginBottom: 9 }}>{s.title}</div>
                <div style={{ fontSize: 15, lineHeight: 1.68, color: '#4a453d', maxWidth: 760 }}>{s.desc}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ borderTop: '1px solid #d8d3c7', background: '#efece4' }}>
        <div className="shell" style={{ paddingTop: 'clamp(46px, 5.5vw, 70px)', paddingBottom: 'clamp(46px, 5.5vw, 70px)' }}>
          <MonoLabel style={{ marginBottom: 18 }}>Ten lanes, one mechanized</MonoLabel>
          <p style={{ margin: '0 0 28px', fontSize: 15.5, lineHeight: 1.7, color: '#4a453d', maxWidth: 760 }}>
            The core type and effect system is machine-checked in Coq. The other prover trees in the repository are machine-generated from those sources; they exist, they are graded, and they are not independent re-verification. No external audit has been published.
          </p>
          <div className="noscroll" style={{ overflowX: 'auto', border: '1px solid #c9c3b4', background: '#fffdf8' }}>
            <div style={{ minWidth: 620 }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr 1fr 1.4fr', padding: '12px 20px', background: '#e9e5db', borderBottom: '1px solid #c9c3b4', fontFamily: 'var(--font-mono)', fontSize: 10, letterSpacing: '0.12em', textTransform: 'uppercase', color: '#6b6559' }}>
                <span>Prover</span><span>Artefacts</span><span>Claim level</span><span>Role</span>
              </div>
              {lanes.map(l => {
                const mech = l.level === 'mechanized';
                return (
                  <div key={l.prover} style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr 1fr 1.4fr', padding: '13px 20px', borderBottom: '1px solid #e6e1d6', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: 13.5, color: mech ? '#14120f' : '#6b6559', fontWeight: mech ? 600 : 400 }}>{l.prover}</span>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: 13, color: '#6b6559' }}>{l.count}</span>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: 10, letterSpacing: '0.1em', textTransform: 'uppercase', color: mech ? '#f5f3ee' : '#6b6559', background: mech ? '#14120f' : 'transparent', border: `1px solid ${mech ? '#14120f' : '#c9c3b4'}`, padding: '3px 8px', justifySelf: 'start' }}>{l.level}</span>
                    <span style={{ fontSize: 13.5, color: '#4a453d' }}>{l.role}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      <div style={{ borderTop: '1px solid #d8d3c7' }}>
        <div className="shell" style={{ paddingTop: 'clamp(46px, 5.5vw, 70px)', paddingBottom: 'clamp(46px, 5.5vw, 70px)' }}>
          <MonoLabel style={{ marginBottom: 18 }}>Research coverage</MonoLabel>
          <p style={{ margin: '0 0 26px', fontSize: 15.5, lineHeight: 1.7, color: '#4a453d', maxWidth: 760 }}>
            Tracks spanning the full stack, from type-theory foundations to hardware side-channel models.
          </p>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 1, background: '#e6e1d6', border: '1px solid #e6e1d6' }}>
            {RESEARCH.map(d => (
              <div key={d.name} style={{ background: '#fffdf8', padding: '20px 22px' }}>
                <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>{d.name}</div>
                <div style={{ fontSize: 13.5, lineHeight: 1.6, color: '#4a453d' }}>{d.desc}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================ COMPLIANCE ============================ */

function Compliance() {
  return (
    <div className="rise">
      <div className="shell" style={{ paddingTop: 'clamp(40px, 5vw, 68px)', paddingBottom: 'clamp(28px, 3.4vw, 40px)' }}>
        <MonoLabel style={{ marginBottom: 18 }}>Compliance</MonoLabel>
        <h1 className="serif-h1" style={{ marginBottom: 16, fontSize: 'clamp(36px, 4.6vw, 58px)', maxWidth: 900 }}>Controls stop being assertions and become checks.</h1>
        <p style={{ margin: 0, fontSize: 'clamp(15.5px, 1.2vw, 17px)', lineHeight: 1.65, color: '#3a352d', maxWidth: 720 }}>
          19 profiles, 606 machine-checkable rules. Each rule ships with a violating and a passing test case, so you can see precisely what the checker enforces &mdash; and precisely where it stops.
        </p>
      </div>

      <div className="shell" style={{ paddingBottom: 'clamp(46px, 5.5vw, 68px)' }}>
        <div className="noscroll" style={{ overflowX: 'auto', border: '1px solid #14120f', background: '#fffdf8' }}>
          <div style={{ minWidth: 720 }}>
            <div style={{ display: 'grid', gridTemplateColumns: '0.8fr 1.3fr 1.3fr 0.6fr', padding: '13px 20px', background: '#14120f', color: '#e8e4da', fontFamily: 'var(--font-mono)', fontSize: 10, letterSpacing: '0.12em', textTransform: 'uppercase' }}>
              <span>Framework</span><span>Compiler-checkable slice</span><span>Discharged by</span><span>Status</span>
            </div>
            {FRAMEWORKS.map((f, i) => (
              <div key={i} style={{ display: 'grid', gridTemplateColumns: '0.8fr 1.3fr 1.3fr 0.6fr', padding: '15px 20px', borderBottom: '1px solid #e6e1d6', alignItems: 'center', gap: 10 }}>
                <span style={{ fontSize: 14, fontWeight: 600 }}>{f.fw}</span>
                <span style={{ fontSize: 13.5, color: '#4a453d' }}>{f.req}</span>
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: 12.5, color: f.status === 'MODELLED' ? ACCENT : '#6b6559' }}>{f.th}</span>
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: 10.5, letterSpacing: '0.08em', fontWeight: 600, color: f.status === 'MODELLED' ? '#2f6b3f' : '#8a6d1f' }}>{f.status}</span>
              </div>
            ))}
          </div>
        </div>
        <div style={{ marginTop: 14, fontSize: 13.5, lineHeight: 1.65, color: '#6b6559', maxWidth: 860 }}>
          <span style={{ fontFamily: 'var(--font-mono)', color: '#2f6b3f' }}>MODELLED</span> = a mechanized Coq compliance model exists in <span style={{ fontFamily: 'var(--font-mono)' }}>02_FORMAL/coq/compliance/</span> alongside compiler-enforced rules. <span style={{ fontFamily: 'var(--font-mono)', color: '#8a6d1f' }}>CHECKER</span> = compiler-enforced rules, each with a passing and a violating test case, plus build artefacts (SBOM, CBOM, VEX) where named. Passing a profile is evidence toward a formal assessment and never a substitute for one &mdash; RIINA is a checker, not a conformity assessment body.
        </div>
      </div>

      <div style={{ borderTop: '1px solid #d8d3c7', background: '#efece4' }}>
        <div className="shell" style={{ paddingTop: 'clamp(46px, 5.5vw, 70px)', paddingBottom: 'clamp(46px, 5.5vw, 70px)' }}>
          <MonoLabel style={{ marginBottom: 'clamp(22px, 3vw, 32px)' }}>Sectors</MonoLabel>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: 1, background: '#d8d3c7', border: '1px solid #d8d3c7' }}>
            {SECTORS.map(s => (
              <div key={s.name} style={{ background: '#f5f3ee', padding: '22px 24px 26px' }}>
                <div style={{ fontSize: 16, fontWeight: 600, marginBottom: 5 }}>{s.name}</div>
                <div style={{ fontFamily: 'var(--font-mono)', fontSize: 11.5, color: ACCENT, marginBottom: 10 }}>{s.regs}</div>
                <div style={{ fontSize: 13.5, lineHeight: 1.62, color: '#4a453d' }}>{s.desc}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div style={{ borderTop: '1px solid #d8d3c7' }}>
        <div className="shell" style={{ paddingTop: 'clamp(46px, 5.5vw, 70px)', paddingBottom: 'clamp(46px, 5.5vw, 70px)', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 'clamp(28px, 4vw, 52px)', alignItems: 'start' }}>
          <div>
            <MonoLabel style={{ marginBottom: 18 }}>The artefact</MonoLabel>
            <h2 className="serif-h2" style={{ marginBottom: 14, fontSize: 'clamp(28px, 3vw, 38px)' }}>A report with an integrity hash, not a slide.</h2>
            <p style={{ margin: 0, fontSize: 15.5, lineHeight: 1.68, color: '#4a453d' }}>
              The compiler emits a report naming each rule checked, the violations found, and the SHA-256 of the exact source it examined. Your assessor re-runs the same command and gets the same file. The block on the right is the real output format, abbreviated.
            </p>
          </div>
          <DarkCode pad="clamp(18px, 2vw, 26px)" style={{ fontSize: 'clamp(11.5px, 1vw, 13px)' }}>
            <Prompt />{'riinac check --compliance hipaa --report app.rii\n\n'}
            <Ty>{'RIINA COMPLIANCE REPORT\n'}</Ty>
            {'  File:      app.rii\n  SHA-256:   cc786d8b880bf654325a608d…\n  Verdict:   '}<Sec>PASS</Sec>{'\n\n  Rules checked: 33   Violations: 0\n\n  PROFILE: HIPAA — US Health Insurance\n  Portability and Accountability Act\n  Coverage: 33/54 rules (61.1%)\n  Status: 0 error(s), 0 warning(s)'}
          </DarkCode>
        </div>
      </div>

      <div style={{ borderTop: '1px solid #d8d3c7', background: '#efece4' }}>
        <div className="shell" style={{ paddingTop: 'clamp(48px, 5.5vw, 72px)', paddingBottom: 'clamp(48px, 5.5vw, 72px)', display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', alignItems: 'flex-end', gap: 32 }}>
          <div style={{ maxWidth: 620 }}>
            <h2 className="serif-h2" style={{ marginBottom: 14, fontSize: 'clamp(30px, 3.4vw, 42px)', lineHeight: 1.1 }}>Bring your hardest requirement.</h2>
            <p style={{ margin: 0, fontSize: 15.5, lineHeight: 1.66, color: '#4a453d' }}>
              Thirty minutes, your framework, a live checker run against it. If the answer is that we cannot cover it, you will hear that instead.
            </p>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10, flexShrink: 0 }}>
            <a href="mailto:ikmal.baharudin@gmail.com?subject=RIINA%20Enterprise%20Evaluation" className="hov-dark-btn" style={{ fontSize: 15, fontWeight: 500, background: '#14120f', color: '#f5f3ee', padding: '15px 26px', textAlign: 'center' }}>
              Request a review
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}

