/* ============================ APP ============================ */

const PAGES = ['home', 'evidence', 'language', 'arch', 'compliance', 'playground', 'docs'];

export default function RiinaWebsite() {
  const { metrics } = useMetrics();
  const [page, setPage] = useState(() => {
    const h = (typeof window !== 'undefined' ? window.location.hash : '').replace(/^#\/?/, '');
    return PAGES.includes(h) ? h : 'home';
  });

  const go = useCallback((p) => {
    setPage(p);
    if (typeof window !== 'undefined') {
      window.history.replaceState(null, '', p === 'home' ? '#' : `#/${p}`);
      window.scrollTo({ top: 0, behavior: 'auto' });
    }
  }, []);

  useEffect(() => {
    const onHash = () => {
      const h = window.location.hash.replace(/^#\/?/, '');
      if (PAGES.includes(h)) setPage(h);
      else if (h === '') setPage('home');
    };
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  return (
    <div style={{ minHeight: '100vh', background: '#f5f3ee' }}>
      <Header page={page} go={go} />
      {page === 'home' && <Home go={go} metrics={metrics} />}
      {page === 'evidence' && <Evidence metrics={metrics} />}
      {page === 'language' && <Language />}
      {page === 'arch' && <Architecture metrics={metrics} />}
      {page === 'compliance' && <Compliance />}
      {page === 'playground' && <Playground />}
      {page === 'docs' && <Docs go={go} metrics={metrics} />}
      <Footer go={go} metrics={metrics} />
    </div>
  );
}
